// Общие шаги для тестов карты (#2a31ff, #46db57): эмуляция геолокации, вкл/выкл шаринга, ответ nearby_live, предпочтения.
// Написано вручную, не проверено на живой странице — проверить при первом /qa-regress (особенно путь к «העדפות חיפוש» и пины карты).
import { expect, type Page, type Response } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';

// Фиктивные координаты (Тель-Авив, в пределах ~250 м друг от друга). Реальная геолокация не используется.
export const GEO = {
  free: { latitude: 32.0853, longitude: 34.7818 },
  user4: { latitude: 32.0868, longitude: 34.7802 },
  user2: { latitude: 32.084, longitude: 34.7832 },
} as const;
export type GeoRole = keyof typeof GEO;

// iPhone 390×844 (сценарий тикетов). Проект data — Chromium, поэтому размер задаём на странице.
export async function setupMapUser(page: Page, role: GeoRole) {
  await page.setViewportSize({ width: 390, height: 844 });
  const cfg = JSON.parse(fs.readFileSync(path.resolve(__dirname, '../../qa.config.json'), 'utf8'));
  const origin = new URL(process.env.QA_BASE_URL || cfg.baseUrl).origin;
  await page.context().grantPermissions(['geolocation'], { origin });
  await page.context().setGeolocation({ ...GEO[role], accuracy: 10 });
}

// id пользователя из сохранённой сессии .qa/auth/<role>.json (Supabase auth-token в localStorage).
export function userIdOf(role: string): string {
  const file = path.resolve(__dirname, '../../../auth', `${role}.json`);
  const state = JSON.parse(fs.readFileSync(file, 'utf8'));
  for (const o of state.origins ?? []) {
    for (const kv of o.localStorage ?? []) {
      if (/auth-token/.test(kv.name)) {
        const id = JSON.parse(kv.value)?.user?.id;
        if (id) return id;
      }
    }
  }
  throw new Error(`Нет user.id в .qa/auth/${role}.json — перелогинь роль (qa-login:manual -- ${role})`);
}

export type NearbyRow = Record<string, unknown>;
export const rowId = (r: NearbyRow) => String(r.id ?? r.user_id ?? r.profile_id ?? '');

const isNearby = (r: Response) => r.url().includes('/rpc/nearby_live') && r.request().method() === 'POST';
const isSharePatch = (r: Response) =>
  r.request().method() === 'PATCH' && r.url().includes('/rest/v1/profiles') && (r.request().postData() ?? '').includes('share_location');

const offCard = (page: Page) => page.getByText('שיתוף מיקום כבוי');
const enableBtn = (page: Page) => page.getByRole('button', { name: 'הפעלת שיתוף מיקום' }).or(page.getByText('הפעלת שיתוף מיקום'));
const pill = (page: Page) => page.getByText('שיתוף מיקום פעיל');

// Открыть карту и дождаться одного из двух состояний: шаринг выключен (карточка) или включён (пилюля).
export async function openMap(page: Page) {
  await page.goto('/map');
  await expect(offCard(page).or(pill(page)).first()).toBeVisible();
}

// Включить шаринг кнопкой из объяснения; ждёт PATCH share_location=true.
export async function enableSharing(page: Page) {
  await openMap(page);
  if (await pill(page).isVisible()) return;
  const patch = page.waitForResponse(isSharePatch);
  await enableBtn(page).first().click();
  const res = await patch;
  expect(res.ok()).toBeTruthy();
  expect(res.request().postDataJSON()).toMatchObject({ share_location: true });
  await expect(pill(page)).toBeVisible();
}

// Выключить шаринг через пилюлю → «לכבות את שיתוף המיקום?» → «כיבוי שיתוף מיקום». Безопасно, если уже выключен.
export async function disableSharing(page: Page) {
  await openMap(page);
  if (await offCard(page).isVisible()) return;
  await pill(page).click();
  await expect(page.getByText('לכבות את שיתוף המיקום?')).toBeVisible();
  const patch = page.waitForResponse(isSharePatch);
  await page.getByText('כיבוי שיתוף מיקום', { exact: true }).click();
  const res = await patch;
  expect(res.request().postDataJSON()).toMatchObject({ share_location: false });
  await expect(offCard(page)).toBeVisible();
}

// Перезагрузить карту и вернуть строки ответа rpc/nearby_live.
export async function fetchNearby(page: Page): Promise<NearbyRow[]> {
  const wait = page.waitForResponse(isNearby);
  await page.reload();
  const res = await wait;
  expect(res.status()).toBe(200);
  const body = await res.json();
  return Array.isArray(body) ? body : [];
}

// Ждать, пока в nearby_live у page появится (present=true) или исчезнет (false) пользователь id.
// Другие видят изменения с задержкой опроса (#0f19c0) — поэтому повторяем перезагрузку, без фиксированных пауз.
export async function expectInNearby(page: Page, id: string, present: boolean, timeout = 60_000) {
  await expect
    .poll(async () => (await fetchNearby(page)).some((r) => rowId(r) === id), {
      message: `nearby_live ${present ? 'содержит' : 'не содержит'} ${id}`,
      timeout,
      intervals: [2_000, 3_000, 5_000],
    })
    .toBe(present);
}

// Предпочтения «רוצה להכיר»: свой профиль → ⚙ → «הגדרות» → «העדפות חיפוש» → «גברים»/«נשים» → «שמירה».
// Путь взят из брифа #01a5ce (Figma 869-8146) и кадра 46db57-R3-free-prefs-restored — НЕ проверен автотестом.
export async function setWantToMeet(page: Page, who: 'גברים' | 'נשים') {
  await page.goto('/discover');
  await page.getByText('פרופיל', { exact: true }).last().click();
  await page.getByRole('button', { name: /הגדרות|settings/i }).or(page.getByLabel(/הגדרות/)).first().click();
  await page.getByText('העדפות חיפוש').first().click();
  await expect(page.getByText('רוצה להכיר')).toBeVisible();
  await page.getByText(who, { exact: true }).click();
  const save = page.waitForResponse((r) => ['PATCH', 'POST'].includes(r.request().method()) && r.url().includes('/rest/v1/'));
  await page.getByRole('button', { name: 'שמירה' }).or(page.getByText('שמירה', { exact: true })).first().click();
  expect((await save).ok()).toBeTruthy();
}
